import React from 'react';
import { FaTrash, FaShieldAlt, FaEnvelope } from 'react-icons/fa';
import { useTheme } from '../../context/ThemeContext';
import styles from './NotificationItem.module.css';

const NotificationItem = ({ notification, onDelete }) => {
    const { theme } = useTheme();

    const formatDate = (dateStr) => {
        if (!dateStr) return '';
        const date = new Date(dateStr);
        return date.toLocaleString('ru-RU', {
            day: 'numeric',
            month: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    const isAdminNotification = notification.NotificationType === 'admin' || notification.Text?.startsWith('[АДМИН]');
    const displayText = isAdminNotification
        ? notification.Text.replace('[АДМИН] ', '')
        : notification.Text;

    return (
        <div
            className={`${styles.notificationItem} ${!notification.IsRead ? styles.unread : ''}`}
            data-theme={theme}
        >
            <div className={styles.notificationIcon}>
                {isAdminNotification ? <FaShieldAlt className={styles.adminIcon} /> : <FaEnvelope className={styles.defaultIcon} />}
            </div>
            <div className={styles.notificationContent}>
                {isAdminNotification && (
                    <span className={styles.adminBadge}>От администратора</span>
                )}
                <p className={styles.notificationText}>{displayText}</p>
                <span className={styles.notificationDate}>{formatDate(notification.CreatedDate)}</span>
            </div>
            <button
                className={styles.deleteButton}
                onClick={() => onDelete(notification.Id)}
                aria-label="Удалить уведомление"
            >
                <FaTrash />
            </button>
        </div>
    );
};

export default NotificationItem;
